import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './CSSAdminDashboard.css';

export default function AdminDashboard() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [stats, setStats] = useState({ totalUsers: 0, totalSellers: 0, activeOrders: 0 });
  const [users, setUsers] = useState([]);
  const [auditLogs, setAuditLogs] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState(null);

  // Settings State
  const [settings, setSettings] = useState({
    storeName: 'My E-Commerce Store',
    storeEmail: 'support@ecommerce.com',
    currency: 'USD ($)',
    taxRate: '5%',
    enableNotifications: true,
    maintenanceMode: false,
  });

  // Fetch live dashboard data every 5 seconds
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get('http://localhost:4000/api/admin/data');
        setStats(response.data.stats || {});
        setUsers(response.data.users || []);
        setAuditLogs(response.data.auditLogs || []);
      } catch (error) {
        console.error('Error fetching admin data:', error);
      }
    };

    fetchData();
    const interval = setInterval(fetchData, 5000);
    return () => clearInterval(interval);
  }, []);

  const handleSettingsChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSettings((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleSettingsSubmit = (e) => {
    e.preventDefault();
    // Example: Add axios PUT request here to persist changes to your backend
    alert('Settings saved successfully!');
  };

  const toggleUserStatus = async (userId) => {
    try {
      await axios.patch(`http://localhost:4000/api/admin/users/${userId}/toggle`);
      setUsers(users.map(u => u.id === userId ? { ...u, status: u.status === 'active' ? 'blocked' : 'active' } : u));
    } catch (error) {
      console.error('Failed to toggle user status', error);
    }
  };

  const filteredUsers = users.filter(user => 
    user.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.email?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="admin-wrapper">
      {/* Sidebar Navigation */}
      <aside className="admin-sidebar">
        <h2>Admin Panel</h2>
        <ul>
          <li className={activeTab === 'dashboard' ? 'active' : ''} onClick={() => setActiveTab('dashboard')}>
            Dashboard Overview
          </li>
          <li className={activeTab === 'users' ? 'active' : ''} onClick={() => setActiveTab('users')}>
            User Info
          </li>
          <li className={activeTab === 'sellers' ? 'active' : ''} onClick={() => setActiveTab('sellers')}>
            Seller Info
          </li>
          <li className={activeTab === 'audit' ? 'active' : ''} onClick={() => setActiveTab('audit')}>
            Audit Logs
          </li>
          <li className={activeTab === 'settings' ? 'active' : ''} onClick={() => setActiveTab('settings')}>
            Store Settings
          </li>
        </ul>
      </aside>

      {/* Main Content Area */}
      <main className="admin-main">
        <header className="admin-header">
          <h1>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)} Management</h1>
          <div className="admin-profile">Admin User</div>
        </header>

        <div className="admin-content">
          {/* DASHBOARD OVERVIEW TAB */}
          {activeTab === 'dashboard' && (
            <div className="dashboard-overview">
              <div className="stats-grid">
                <div className="stat-card">
                  <h3>Total Users</h3>
                  <p>{stats.totalUsers}</p>
                </div>
                <div className="stat-card">
                  <h3>Total Sellers</h3>
                  <p>{stats.totalSellers}</p>
                </div>
                <div className="stat-card">
                  <h3>Active Orders</h3>
                  <p>{stats.activeOrders}</p>
                </div>
              </div>
            </div>
          )}

          {/* USER INFO TAB */}
          {activeTab === 'users' && (
            <div className="user-management">
              <div className="table-controls">
                <input 
                  type="text" 
                  placeholder="Search users by name or email..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="search-input"
                />
              </div>
              <div className="table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>Name</th>
                      <th>Email</th>
                      <th>Role</th>
                      <th>Status</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredUsers.map(user => (
                      <tr key={user.id}>
                        <td>{user.name}</td>
                        <td>{user.email}</td>
                        <td>{user.role}</td>
                        <td>
                          <span className={`status-badge ${user.status}`}>
                            {user.status}
                          </span>
                        </td>
                        <td>
                          <button className="btn-action" onClick={() => setSelectedUser(user)}>View</button>
                          <button className="btn-action toggle" onClick={() => toggleUserStatus(user.id)}>
                            {user.status === 'active' ? 'Block' : 'Unblock'}
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* AUDIT LOGS TAB */}
          {activeTab === 'audit' && (
            <div className="audit-logs">
              <div className="table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>Timestamp</th>
                      <th>User</th>
                      <th>Action</th>
                      <th>Details</th>
                    </tr>
                  </thead>
                  <tbody>
                    {auditLogs.map((log, index) => (
                      <tr key={index}>
                        <td>{new Date(log.timestamp).toLocaleString()}</td>
                        <td>{log.userEmail}</td>
                        <td>{log.action}</td>
                        <td>{log.details}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* SETTINGS SECTION TAB */}
          {activeTab === 'settings' && (
            <div className="admin-settings-section">
              <h2>Store Settings</h2>
              <p className="section-subtitle">Manage your e-commerce platform preferences and configurations.</p>
              
              <form onSubmit={handleSettingsSubmit} className="settings-form">
                <div className="settings-card">
                  <h3>General Information</h3>
                  
                  <div className="form-group">
                    <label htmlFor="storeName">Store Name</label>
                    <input
                      type="text"
                      id="storeName"
                      name="storeName"
                      value={settings.storeName}
                      onChange={handleSettingsChange}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label htmlFor="storeEmail">Support Email</label>
                    <input
                      type="email"
                      id="storeEmail"
                      name="storeEmail"
                      value={settings.storeEmail}
                      onChange={handleSettingsChange}
                      required
                    />
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label htmlFor="currency">Currency</label>
                      <select
                        id="currency"
                        name="currency"
                        value={settings.currency}
                        onChange={handleSettingsChange}
                      >
                        <option value="USD ($)">USD ($)</option>
                        <option value="EUR (€)">EUR (€)</option>
                        <option value="INR (₹)">INR (₹)</option>
                        <option value="GBP (£)">GBP (£)</option>
                      </select>
                    </div>

                    <div className="form-group">
                      <label htmlFor="taxRate">Default Tax Rate</label>
                      <input
                        type="text"
                        id="taxRate"
                        name="taxRate"
                        value={settings.taxRate}
                        onChange={handleSettingsChange}
                      />
                    </div>
                  </div>
                </div>

                <div className="settings-card">
                  <h3>System Preferences</h3>
                  
                  <div className="form-group checkbox-group">
                    <label>
                      <input
                        type="checkbox"
                        name="enableNotifications"
                        checked={settings.enableNotifications}
                        onChange={handleSettingsChange}
                      />
                      Enable Email Notifications for New Orders
                    </label>
                  </div>

                  <div className="form-group checkbox-group">
                    <label>
                      <input
                        type="checkbox"
                        name="maintenanceMode"
                        checked={settings.maintenanceMode}
                        onChange={handleSettingsChange}
                      />
                      Enable Maintenance Mode (Temporarily close store front)
                    </label>
                  </div>
                </div>

                <div className="form-actions">
                  <button type="submit" className="btn-save-settings">Save Changes</button>
                </div>
              </form>
            </div>
          )}
        </div>
      </main>

      {/* User Profile Modal View */}
      {selectedUser && (
        <div className="modal-backdrop">
          <div className="modal-content">
            <h3>User Profile Details</h3>
            <p><strong>Name:</strong> {selectedUser.name}</p>
            <p><strong>Email:</strong> {selectedUser.email}</p>
            <p><strong>Role:</strong> {selectedUser.role}</p>
            <p><strong>Status:</strong> {selectedUser.status}</p>
            <button className="btn-close" onClick={() => setSelectedUser(null)}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}
